// Unit tests for G7-08 cross-cutting ACs (G6-A03/A04/A06) and XLSX, PDF, Markdown, HTML, and hitl Word oracles.
// Uses real synthetic fixtures generated by fixtures-lib and hand-made mutated copies.

import assert from 'node:assert/strict';
import test from 'node:test';
import { fmtVi, q1Shares } from '../fixtures-lib/data.mjs';
import { buildPdf } from '../fixtures-lib/pdf.mjs';
import { buildHtml, buildMarkdown } from '../fixtures-lib/text.mjs';
import { buildXlsx } from '../fixtures-lib/xlsx.mjs';
import { ooxmlEntries, zipStore } from '../fixtures-lib/zip.mjs';
import { readZipEntries } from '../harness/fixture-files.mjs';
import { computeTruth } from '../holdout-xlsx-truth.mjs';
import {
  ROW_EXIT,
  VERDICT,
  blockedVerdict,
  decodeXml,
  extractPdfTextFromBytes,
  failVerdict,
  oracleCapabilityAndToolSurface,
  oracleDocxEdit,
  oracleDocxRead,
  oracleHitlWord,
  oracleHtmlEdit,
  oracleHtmlRead,
  oracleMarkdownEdit,
  oracleMarkdownRead,
  oraclePdfEdit,
  oraclePdfRead,
  oraclePptxEdit,
  oraclePptxRead,
  oracleVersionAndSave,
  oracleXlsxEdit,
  oracleXlsxRead,
  parseDocxStructure,
  parsePptxStructure,
  parseXlsxWorkbookBytes,
  passVerdict,
  validateOoxmlPackage,
} from './oracles.mjs';

const xlsxFixture = buildXlsx();
const pdfFixture = buildPdf();
const mdFixture = buildMarkdown();
const htmlFixture = buildHtml();

function buildEditedXlsxBytes(baseBytes, { mutateCellA2 = false, wrongFormula = false, wrongValue = false } = {}) {
  const entries = readZipEntries(baseBytes);
  const parts = Object.fromEntries(entries.map((e) => [e.name, e.data]));
  const sheets = parseXlsxWorkbookBytes(baseBytes);
  const truth = computeTruth(sheets);
  let sheet1 = parts['xl/worksheets/sheet1.xml'].toString('utf8');

  for (let r = 2; r <= 7; r += 1) {
    const val = wrongValue && r === 2 ? 123 : truth[`cell:Doanh thu Q1!AA${r}`];
    const formula = wrongFormula ? `${val}` : `D${r}*E${r}*(1-IF(F${r}>1,F${r}/100,F${r}))`;
    const cellXml = `<c r="AA${r}" t="n"><f>${formula}</f><v>${val}</v></c>`;
    sheet1 = sheet1.replace(new RegExp(`(<row r="${r}"[^>]*>[\\s\\S]*?)(<\\/row>)`), `$1${cellXml}$2`);
  }
  if (mutateCellA2) {
    sheet1 = sheet1.replace('<c r="A2" t="s"><v>7</v></c>', '<c r="A2" t="s"><v>0</v></c>');
  }
  parts['xl/worksheets/sheet1.xml'] = Buffer.from(sheet1, 'utf8');
  return zipStore(ooxmlEntries(parts));
}

